import{_ as o,o as e,c as r,a3 as d}from"./chunks/framework.BFeCKmyl.js";const h=JSON.parse('{"title":"Cor personalizada do eproc","description":"","frontmatter":{"title":"Cor personalizada do eproc","id":"eproc-favicon-personalizado","plataforma":"eproc","grupo":"Geral do eproc","plano":"free","desde":"1.0.8","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-favicon-personalizado.md","filePath":"funcionalidades/eproc-favicon-personalizado.md"}'),s={name:"funcionalidades/eproc-favicon-personalizado.md"};function c(t,a,n,i,l,p){return e(),r("div",null,a[0]||(a[0]=[d('<h1 id="cor-personalizada-do-eproc" tabindex="-1">Cor personalizada do eproc <a class="header-anchor" href="#cor-personalizada-do-eproc" aria-label="Permalink to &quot;Cor personalizada do eproc&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Troca o ícone da aba do eproc por um na cor que você escolher. Com uma cor diferente da padrão, também recolore as logos da barra superior e da página de login e a animação de carregamento. Ajuda a achar as abas do eproc entre as demais abas abertas.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, ícone da aba do navegador, logos da barra superior e da tela de login e animação de carregamento. A cor escolhida também é usada nos balões de dica do eploc.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Nas configurações do eploc, no card do recurso, escolha a cor.</li><li>Volte ao eproc: a aba e as logos passam a usar a nova cor.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Cor</td><td>#80b3e6 (azul-claro)</td><td>Cor do ícone da aba, das logos, da animação de carregamento e dos balões do eploc.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>A cor é uma só, aplicada a todos os endereços do eproc abertos neste navegador (não há uma cor para cada tribunal ou grau).</li><li>Com a cor padrão, só o ícone da aba é trocado; as logos ficam como no eproc.</li></ul>',11)]))}const b=o(s,[["render",c]]);export{h as __pageData,b as default};
